#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"

/* Prototipos de las funciones de configuración.
 * Operaciones sobre bits usadas en este ejercicio:
 * registro &= ~mascara: limpia los bits seleccionados, conservando los demás.
 * registro |= mascara: pone en 1 los bits seleccionados.
 * registro ^= mascara: invierte los bits seleccionados.
 */
void init_gpio();
void init_tim3();
/*------------------------------------------------------------------*/
int main(void)
{
    //Configuramos PA5 como salida para el LED LD2 de la NUCLEO-F411RE.
    init_gpio();
    //Configuramos TIM3 para generar una interrupción cada 250 ms.
    init_tim3();

    /* El LED se controla en TIM3_IRQHandler; el bucle principal no usa retardos. */
    while (1) {
    }

    return 0;
}


/* ----------------------------------------- */
void init_gpio(){
    //GPIOA necesita su reloj habilitado para acceder a sus registros.
    RCC->AHB1ENR &= ~(RCC_AHB1ENR_GPIOAEN); //Deshabilitamos el reloj; esto no reinicia GPIOA.
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN; //Habilitamos el reloj de GPIOA (bit 0).

    //MODER usa dos bits por pin: limpiamos el campo de PA5 y escribimos 01 (salida).
    GPIOA->MODER &= ~(0b11 << GPIO_MODER_MODER5_Pos); //Limpia solamente los bits 11:10.
    GPIOA->MODER |= (0b01 << GPIO_MODER_MODER5_Pos); //PA5 como salida de propósito general.

    /* OT5 = 0: salida push-pull, capaz de llevar el pin a nivel alto o bajo. */
    GPIOA->OTYPER &= ~(GPIO_OTYPER_OT5); //Selecciona push-pull para PA5.
    
    /* OSPEED5 = 01: velocidad media de los flancos eléctricos de PA5.
     * Este ajuste no determina la frecuencia de parpadeo del LED.
     */
    GPIOA->OSPEEDR &= ~(0b11<<GPIO_OSPEEDR_OSPEED5_Pos); //Limpia el campo de velocidad de PA5.
    GPIOA->OSPEEDR |= (0b01<<GPIO_OSPEEDR_OSPEED5_Pos); //Selecciona velocidad media.
    /* PUPD5 = 00: sin resistencias internas de pull-up ni pull-down. */
    GPIOA->PUPDR &= ~(0b11<< GPIO_PUPDR_PUPD5_Pos); //Desactiva ambas resistencias para PA5.
    /* LD2 es activo en alto: PA5 en bajo deja el LED apagado inicialmente. */
    GPIOA->ODR &= ~(GPIO_ODR_OD5); //OD5 = 0: PA5 en bajo, LED apagado.


}

void init_tim3(){

    //TIM3 está conectado al bus APB1 y necesita su reloj habilitado.
    RCC->APB1ENR &= ~(RCC_APB1ENR_TIM3EN); //Deshabilita el reloj; no reinicia los registros de TIM3.
    RCC->APB1ENR |= (RCC_APB1ENR_TIM3EN); //Habilita el reloj de TIM3.


    TIM3->CNT = 0; //Inicia el contador desde cero.

    /* PSC determina la frecuencia de avance del contador.
     * Con el reloj HSI de arranque, sin cambiar PLL ni divisores del bus,
     * TIM3 recibe 16 MHz (16 000 000 Hz).
     * Frecuencia del contador = reloj de TIM3 / (PSC + 1).
     * Queremos dividir entre 1600: PSC + 1 = 1600, por eso PSC = 1599.
     * 16 000 000 / 1600 = 10 000 Hz: un paso cada 0.1 ms.
     */
    TIM3->PSC = (1600 - 1); 

    /* ARR define el valor máximo del contador en modo ascendente.
     * Cuenta de 0 a ARR; al desbordarse vuelve a cero y genera un update.
     * Para 250 ms: 250 ms / 0.1 ms = 2500 pasos.
     * Como se incluye el cero, ARR + 1 = 2500; escribimos ARR = 2499.
     * Periodo = (PSC + 1) * (ARR + 1) / reloj de TIM3.
     * Periodo actual = 1600 * 2500 / 16 000 000 = 0.25 s = 250 ms.
     *
     * Para cambiar a 500 ms, conserva PSC y usa TIM3->ARR = (5000 - 1).
     * Así: 1600 * 5000 / 16 000 000 = 0.5 s = 500 ms.
     * Si cambias el reloj de TIM3, debes recalcular PSC y ARR.
     */
    TIM3->ARR = (2500 - 1); //2499: 2500 pasos por periodo.
    
    /* CKD = 00: reloj de muestreo de los filtros digitales sin división.
     * CKD no cambia el divisor PSC ni el periodo de este contador interno.
     */
    TIM3->CR1 &= ~(0X3<<TIM_CR1_CKD_Pos); //Limpia el campo CKD.
    

    /* ARPE = 1: las futuras escrituras a ARR quedan en precarga (preload).
     * Se transfieren al registro activo (shadow) en el siguiente update.
     */
    TIM3->CR1 &= ~(TIM_CR1_ARPE); //Limpia el bit ARPE antes de configurarlo.
    TIM3->CR1 |= (TIM_CR1_ARPE); //Habilita la precarga de ARR.
    
    
    TIM3->CR1 &= ~(TIM_CR1_DIR); //DIR = 0: cuenta ascendente; &= conserva los demás bits.

    /* PSC se carga en su divisor activo durante un evento update.
     * Para que el primer intervalo también tenga el periodo calculado,
     * agregar aquí, antes de habilitar la interrupción y arrancar TIM3:
     * TIM3->EGR = TIM_EGR_UG;   //Fuerza un update y carga PSC y ARR.
     * TIM3->SR &= ~TIM_SR_UIF; //Limpia la bandera generada por ese update.
     */
    TIM3->DIER |= (TIM_DIER_UIE); //UIE = 1: permite solicitudes de interrupción por update.

    /* También habilitamos TIM3 en el controlador de interrupciones del procesador. */

    NVIC_EnableIRQ(TIM3_IRQn); //Permite que el procesador atienda la interrupción de TIM3.

    TIM3->CR1 |= (TIM_CR1_CEN); //CEN = 1: arranca el contador con la configuración preparada.

}

/* Rutina de atención de la interrupción de TIM3.
 * El nombre debe coincidir exactamente con TIM3_IRQHandler en el vector
 * de interrupciones del archivo Src/startup_stm32f411xx.S.
 * El procesador entra automáticamente cuando TIM3 solicita una interrupción,
 * porque habilitamos UIE en TIM3 y TIM3_IRQn en el NVIC.
 * No se llama desde main(); al terminar, vuelve al código que estaba ejecutando.
 */

void TIM3_IRQHandler(void){
    /* SR es el registro de estado y contiene las banderas de los eventos.
     * UIF (bit 0) se pone en 1 cuando ocurre un evento update; en este ejercicio,
     * el desbordamiento del contador genera ese evento al completar el periodo.
     * TIM_SR_UIF es la máscara que selecciona únicamente el bit 0.
     * El operador & consulta ese bit sin modificar SR:
     * UIF = 1 -> resultado distinto de cero -> entra en el if.
     * UIF = 0 -> resultado cero -> no entra en el if.
     */
    if(TIM3->SR & TIM_SR_UIF){
        /* Limpiamos UIF para indicar que ya atendimos este evento.
         * TIM_SR_UIF selecciona el bit 0 (...0001).
         * ~TIM_SR_UIF invierte la máscara (...1110).
         * Al aplicar &=, UIF queda en 0 y se conservan las demás banderas.
         * Si no limpiamos UIF, la solicitud puede seguir activa y provocar
         * que el procesador entre inmediatamente otra vez en esta rutina.
         * Esto no deshabilita la interrupción ni detiene el contador:
         * TIM3 volverá a poner UIF en 1 en el siguiente evento update.
         */
        TIM3->SR &= ~(TIM_SR_UIF);

        /* ODR contiene los estados de salida del puerto A.
         * GPIO_ODR_OD5 selecciona el bit 5, correspondiente al pin PA5 (LED LD2).
         * ^= aplica XOR: invierte solamente el bit seleccionado.
         * OD5 = 0 -> pasa a 1 -> LED encendido.
         * OD5 = 1 -> pasa a 0 -> LED apagado.
         * Los demás bits de ODR conservan su valor.
         *
         * Con 250 ms por interrupción: 250 ms encendido y 250 ms apagado.
         * Con 500 ms por interrupción: ciclo completo de 1 segundo.
         * Como el LED comienza apagado, la primera interrupción lo enciende,
         * la segunda lo apaga y las siguientes repiten esta alternancia.
         */
        GPIOA->ODR ^= (GPIO_ODR_OD5);
    }
}

